using System;
using System.Collections.Generic;
using System.Collections.Specialized;
using System.Globalization;
using System.IO;
using System.Text;
using System.Text.Json;
using AwesomeAssertions;
using OptunaSharp.Cli;

namespace OptunaSharp.Tests.Cli;

/// <summary>
///     The CLI's <c>-f yaml</c> writer (<see cref="PyYamlSafeDump" />) against PyYAML's <c>yaml.safe_dump</c>, byte for
///     byte, with no Python at test time: the committed corpus <c>oracle/pyyaml_safe_dump.json</c> (763 cases, PyYAML
///     6.0.3, regenerated by <c>oracle/gen_pyyaml_oracle.py</c>) pairs value trees with PyYAML's output.
/// </summary>
/// <remarks>
///     The corpus is built to reach every style decision: YAML 1.1 look-alike strings that must be quoted to stay strings,
///     indicators in every position, quotes and doubled quotes, leading / trailing / doubled spaces, line breaks, control,
///     non-ASCII and astral characters (escaped, since <c>allow_unicode</c> is off), strings that fold at 80 columns in
///     each of the plain, single- and double-quoted styles, floats from <c>5e-324</c> to <c>.inf</c> and <c>-0.0</c>, keys
///     around the 128-character simple-key limit, empty and nested collections, and 190 CLI-shaped trial records. Found
///     with it: QA-61 of <c>docs/qa/PARITY_QA_2026-11-10.md</c> (YamlDotNet, used before, changed value types).
/// </remarks>
[TestClass]
public class PyYamlSafeDumpOracleTests
{
    /// <summary>
    ///     Every case of the corpus dumps to PyYAML's exact text; a failure lists the first mismatches with both texts.
    /// </summary>
    /// <exception cref="AssertFailedException">A case's output differs from PyYAML's.</exception>
    [TestMethod]
    public void SafeDump_EveryCorpusCase_MatchesPyYamlByteForByte()
    {
        string path = Path.Combine(AppContext.BaseDirectory, "oracle", "pyyaml_safe_dump.json");
        using JsonDocument doc = JsonDocument.Parse(File.ReadAllText(path, Encoding.UTF8));
        JsonElement cases = doc.RootElement.GetProperty("cases");

        var failures = new List<string>();
        int index = 0, mismatches = 0;
        foreach (JsonElement c in cases.EnumerateArray())
        {
            object? tree = Untag(c.GetProperty("tree"));
            string expected = c.GetProperty("yaml").GetString()!;
            string actual = PyYamlSafeDump.Dump(tree);
            if (actual != expected)
            {
                // Keep the first ten in full for the message; count all of them.
                mismatches++;
                if (failures.Count < 10)
                    failures.Add($"case {index}:\n--- PyYAML\n{expected}--- port\n{actual}");
            }
            index++;
        }

        index.Should().Be(763, "the corpus is complete");
        mismatches.Should().Be(0, string.Join("\n", failures));
    }

    /// <summary>The CLI's float forms, pinned by name: a decimal point always, <c>.0</c> before a bare exponent.</summary>
    /// <param name="value">The float.</param>
    /// <param name="expected">PyYAML's line for <c>{"v": value}</c>.</param>
    [TestMethod]
    [DataRow(2.0, "v: 2.0\n")]
    [DataRow(1e-07, "v: 1.0e-07\n")]
    [DataRow(1e16, "v: 1.0e+16\n")]
    [DataRow(double.NaN, "v: .nan\n")]
    [DataRow(double.NegativeInfinity, "v: -.inf\n")]
    [DataRow(-0.0, "v: -0.0\n")]
    public void SafeDump_Floats_KeepPyYamlsFloatForms(double value, string expected)
    {
        var tree = new OrderedDictionary { ["v"] = value };

        PyYamlSafeDump.Dump(tree).Should().Be(expected);
    }

    /// <summary>
    ///     Rebuilds a Python value from the corpus's tagged JSON (see the generator's docstring): dicts become
    ///     <see cref="OrderedDictionary" />, lists <see cref="List{T}" />, ints <see cref="long" />, floats their exact
    ///     bits.
    /// </summary>
    /// <param name="e">A tagged node.</param>
    /// <returns>The value as the CLI would hand it to the dumper.</returns>
    /// <exception cref="InvalidDataException">The node has an unknown tag (a corrupt corpus).</exception>
    private static object? Untag(JsonElement e)
    {
        JsonProperty p = default;
        foreach (JsonProperty only in e.EnumerateObject())
            p = only;
        switch (p.Name)
        {
            case "n":
                return null;
            case "b":
                return p.Value.GetBoolean();
            case "i":
                return long.Parse(p.Value.GetString()!, NumberStyles.AllowLeadingSign, CultureInfo.InvariantCulture);
            case "f":
                return BitConverter.Int64BitsToDouble(p.Value.GetInt64());
            case "s":
                return p.Value.GetString();
            case "l":
            {
                var list = new List<object?>();
                foreach (JsonElement item in p.Value.EnumerateArray())
                    list.Add(Untag(item));
                return list;
            }
            case "d":
            {
                var dict = new OrderedDictionary();
                foreach (JsonElement pair in p.Value.EnumerateArray())
                    dict[Untag(pair[0])!] = Untag(pair[1]);
                return dict;
            }
            default:
                throw new InvalidDataException($"unknown tag '{p.Name}' in the PyYAML corpus");
        }
    }
}
